import{_ as l,C as h,o as i,c,ah as a,E as o,j as d,a as r}from"./chunks/framework.DuX8SFU5.js";const N=JSON.parse('{"title":"AM_CAN_LOGGER — даташит","description":"","frontmatter":{"title":"AM_CAN_LOGGER — даташит","pdf":"/pdf/AM_CAN_LOGGER_datasheet.pdf","pdfStyle":"datasheet","pageClass":"datasheet-page","preliminary":true},"headers":[],"relativePath":"am_can_logger/datasheet.md","filePath":"am_can_logger/datasheet.md"}'),n={name:"am_can_logger/datasheet.md"};function s(_,t,p,b,u,A){const e=h("AssetImage");return i(),c("div",null,[t[0]||(t[0]=a('<h2 id="_1-описание" tabindex="-1">1. Описание <a class="header-anchor" href="#_1-описание" aria-label="Permalink to &quot;1. Описание&quot;">​</a></h2><p>AM_CAN_LOGGER — автономный регистратор CAN-трафика и вибраций на базе полётного контроллера Pixhawk 6X (FMUv6X) с прошивкой на основе PX4. Он слушает две шины CAN, не передавая в них ничего, и записывает каждый кадр с меткой времени на карту microSD; при выгрузке запись превращается в формат <code>candump</code>. Параллельно в журнал ULog пишутся состояние регистратора и, по выбору, сырые данные акселерометра и гироскопа с полной частотой датчика. Прошивка запускает только то, что нужно регистратору, без оценки положения, регуляторов и навигации полётного контроллера: освободившаяся память идёт под буфер записи.</p><h2 id="_2-возможности" tabindex="-1">2. Возможности <a class="header-anchor" href="#_2-возможности" aria-label="Permalink to &quot;2. Возможности&quot;">​</a></h2><ul><li>Две шины CAN, скорость каждой задаётся отдельно, от 10 кбит/с до 1 Мбит/с, или определяется автоматически.</li><li>Режим только приёма: контроллер CAN не подтверждает кадры и не выдаёт ошибок; автоподбор скорости тоже ничего не передаёт.</li><li>Метка времени ставится в прерывании приёма кадра, с разрешением 1 мкс.</li><li>Компактная двоичная запись, около 16 байт на кадр против около 48 в тексте <code>candump</code>; новый файл каждые 10 минут. Текст <code>candump -L</code> прямо на карту включается параметром.</li><li>Места и число потерянных кадров отмечаются в самой записи.</li><li>Сырые данные акселерометра и гироскопа в ULog для анализа вибраций.</li><li>Автозапуск при подаче питания, запись с момента загрузки.</li><li>Счётчики кадров и потерь по каждой шине, раз в секунду в ULog.</li><li>Текстовые отметки событий в отдельном файле рядом с записью и в ULog.</li><li>Индикация состояния светодиодом.</li><li><a href="#dashboard">Веб-панель</a> по USB: состояние, графики загрузки шин и карты, выгрузка и удаление файлов, настройки, разбор протоколов DroneCAN, CANopen и J1939, живой поток кадров для DroneCAN GUI Tool.</li></ul><h2 id="_3-характеристики" tabindex="-1">3. Характеристики <a class="header-anchor" href="#_3-характеристики" aria-label="Permalink to &quot;3. Характеристики&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Параметр</th><th>Мин.</th><th>Тип.</th><th>Макс.</th><th>Ед.</th><th>Примечание</th></tr></thead><tbody><tr><td>Число шин CAN</td><td>—</td><td>2</td><td>2</td><td></td><td>CAN1 и CAN2 контроллера</td></tr><tr><td>Скорость шины</td><td>10</td><td>—</td><td>1000</td><td>кбит/с</td><td>Для каждой шины своя</td></tr><tr><td>Скорости автоподбора</td><td></td><td></td><td></td><td>кбит/с</td><td>10, 20, 50, 125, 250, 500, 800, 1000</td></tr><tr><td>Время автоподбора</td><td>—</td><td>1</td><td>—</td><td>с</td><td>Измерено на стенде</td></tr><tr><td>Формат кадров</td><td></td><td></td><td></td><td></td><td>Классический CAN, 11 и 29 бит; CAN FD не поддерживается</td></tr><tr><td>Разрешение метки времени</td><td>—</td><td>1</td><td>—</td><td>мкс</td><td></td></tr><tr><td>Запись на карту на кадр</td><td>15</td><td>16</td><td>17</td><td>Б</td><td>Двоичный формат; в тексте <code>candump</code> около 48</td></tr><tr><td>Пропускная способность записи без потерь, пачка</td><td>—</td><td>—</td><td>10,5</td><td>тыс. кадр/с</td><td>2 с, измерено на стенде</td></tr><tr><td>Потери за 50 ч записи, 3,7 тыс. кадр/с</td><td>—</td><td>0,006</td><td>—</td><td>%</td><td>Две шины, 1 Мбит/с и 500 кбит/с, стенд</td></tr><tr><td>Длительность файла</td><td>0</td><td>600</td><td>3600</td><td>с</td><td>0 — без деления на файлы</td></tr><tr><td>Буфер между приёмом и картой</td><td>4</td><td>320</td><td>512</td><td>КиБ</td><td>Размер, который не помещается в память, уменьшается вдвое</td></tr><tr><td>Синхронизация файла на карту</td><td>—</td><td>1</td><td>—</td><td>с</td><td></td></tr><tr><td>Частота записи IMU</td><td>—</td><td>400</td><td>—</td><td>сообщ./с</td><td>Пакеты отсчётов с полной частотой датчика</td></tr><tr><td>Объём записи при 3,7 тыс. кадр/с</td><td>—</td><td>0,2</td><td>—</td><td>ГБ/ч</td><td>Измерено за 50 ч</td></tr><tr><td>Выгрузка по USB</td><td>—</td><td>0,5</td><td>—</td><td>МБ/с</td><td></td></tr></tbody></table><p>Предел записи — карта памяти, а не приём кадров. Время от времени карта останавливает запись на несколько секунд для внутреннего обслуживания (на стенде — до 6,6 с), и буфер должен перекрыть такую остановку на текущем потоке: 320 КиБ при 60 КиБ/с хватает примерно на 5 с. Все потери за 50 часов на стенде — переполнения буфера во время таких остановок. Сырые данные IMU добавляют к потоку на карту около 200 КиБ/с, поэтому при плотном CAN-потоке их стоит выключать.</p><h2 id="_4-подключение" tabindex="-1">4. Подключение <a class="header-anchor" href="#_4-подключение" aria-label="Permalink to &quot;4. Подключение&quot;">​</a></h2><h3 id="_4-1-разъемы-can1-и-can2" tabindex="-1">4.1. Разъёмы CAN1 и CAN2 <a class="header-anchor" href="#_4-1-разъемы-can1-и-can2" aria-label="Permalink to &quot;4.1. Разъёмы CAN1 и CAN2&quot;">​</a></h3><p>JST-GH, 4 контакта, по стандарту разъёмов Pixhawk:</p><table tabindex="0"><thead><tr><th>Конт.</th><th>Сигнал</th></tr></thead><tbody><tr><td>1</td><td>5 В</td></tr><tr><td>2</td><td>CAN_H</td></tr><tr><td>3</td><td>CAN_L</td></tr><tr><td>4</td><td>GND</td></tr></tbody></table><p>Контакт 5 В к шине машины не подключается.</p><h3 id="_4-2-питание" tabindex="-1">4.2. Питание <a class="header-anchor" href="#_4-2-питание" aria-label="Permalink to &quot;4.2. Питание&quot;">​</a></h3><p>Контроллер питается через модуль питания на разъём POWER; от бортовой сети 24 В питание подаётся через преобразователь и предохранитель.</p><h2 id="_5-данные-на-карте" tabindex="-1">5. Данные на карте <a class="header-anchor" href="#_5-данные-на-карте" aria-label="Permalink to &quot;5. Данные на карте&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Путь</th><th>Содержимое</th></tr></thead><tbody><tr><td><code>log/&lt;дата&gt;/&lt;время&gt;_can_NNNN.amcan</code></td><td>CAN-кадры; новый файл каждые 10 минут</td></tr><tr><td><code>log/&lt;дата&gt;/&lt;время&gt;_events.log</code></td><td>Отметки событий</td></tr><tr><td><code>log/&lt;дата&gt;/&lt;время&gt;.ulg</code></td><td>ULog: состояние регистратора, по выбору — IMU</td></tr></tbody></table><p>Запись CAN лежит в папке журнала ULog той же сессии; пока часы контроллера не выставлены, папка называется <code>sessNNN</code>. Если журнал ULog не ведётся, запись лежит в <code>candump/sessNNN/</code>. Автоматическая очистка старых сессий (нехватка места, параметр <code>SDLOG_DIRS_MAX</code>) удаляет запись CAN вместе с её журналом.</p><p>Двоичная запись начинается с заголовка, в котором указаны скорость и протокол каждой шины. Дальше идут кадры, метки абсолютного времени в начале и каждые 100 мс и записи о потерях с числом потерянных кадров. Панель выгружает её в формате <code>candump</code>:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>(1712345678.123456) can0 18EEFF01#0102030405060708</span></span></code></pre></div><p><code>can0</code> — шина CAN1, <code>can1</code> — шина CAN2. Время в скобках — секунды и микросекунды по часам контроллера. Отметки событий записаны на тех же часах; в скобках — имя, если оно задано в панели:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>(1712345678.123456) начало бурения [Оператор]</span></span></code></pre></div><h2 id="_6-параметры" tabindex="-1">6. Параметры <a class="header-anchor" href="#_6-параметры" aria-label="Permalink to &quot;6. Параметры&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Параметр</th><th>По умолчанию</th><th>Назначение</th></tr></thead><tbody><tr><td><code>SYS_AUTOSTART</code></td><td>22001</td><td>Конфигурация регистратора: запускает только то, что ему нужно</td></tr><tr><td><code>CANLOG_EN</code></td><td>1</td><td>Запуск регистратора при загрузке</td></tr><tr><td><code>CANLOG_BITRATE1</code></td><td>1000000</td><td>Скорость шины CAN1, бит/с; 0 — определять автоматически</td></tr><tr><td><code>CANLOG_BITRATE2</code></td><td>1000000</td><td>Скорость шины CAN2, бит/с; 0 — определять автоматически</td></tr><tr><td><code>CANLOG_PROTO1</code></td><td>0</td><td>Протокол шины CAN1 для разбора в панели: 0 — определять, 1 — DroneCAN, 2 — CANopen, 3 — J1939</td></tr><tr><td><code>CANLOG_PROTO2</code></td><td>0</td><td>То же для шины CAN2</td></tr><tr><td><code>CANLOG_IFACES</code></td><td>3</td><td>Маска шин: бит 0 — CAN1, бит 1 — CAN2</td></tr><tr><td><code>CANLOG_SILENT</code></td><td>1</td><td>Только приём</td></tr><tr><td><code>CANLOG_ROT_S</code></td><td>600</td><td>Длительность файла, с; 0 — не делить</td></tr><tr><td><code>CANLOG_BUF_KB</code></td><td>320</td><td>Буфер между приёмом и картой, КиБ</td></tr><tr><td><code>CANLOG_FORMAT</code></td><td>1</td><td>1 — двоичная запись (<code>.amcan</code>), 0 — текст <code>candump</code> (<code>.log</code>)</td></tr><tr><td><code>UAVCAN_ENABLE</code></td><td>0</td><td>Должен быть 0: регистратор сам управляет контроллером CAN</td></tr><tr><td><code>SDLOG_MODE</code></td><td>2</td><td>Журнал ULog с момента загрузки</td></tr><tr><td><code>SDLOG_PROFILE</code></td><td>4096</td><td>Только состояние регистратора, около 2 КиБ/с; 4864 — плюс сырые данные IMU; 1 — полный журнал PX4, около 40 КиБ/с; 769 — полный плюс IMU</td></tr></tbody></table><p>Значения по умолчанию даны для конфигурации 22001; значения, уже сохранённые на контроллере, она не меняет. Изменения вступают в силу после перезагрузки.</p><h2 id="_7-индикация" tabindex="-1">7. Индикация <a class="header-anchor" href="#_7-индикация" aria-label="Permalink to &quot;7. Индикация&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Состояние</th><th>Условие</th><th>Светодиод контроллера</th><th>Внешний RGB-светодиод</th></tr></thead><tbody><tr><td>Запись</td><td>Все включённые шины передали кадры за последние 2 с, потерь нет</td><td>1 Гц</td><td>зелёный, медленно</td></tr><tr><td>Тишина на шине</td><td>Одна из шин молчит дольше 2 с</td><td>короткая вспышка раз в 2 с</td><td>жёлтый, медленно</td></tr><tr><td>Потери</td><td>Потеря кадра или ошибка записи за последние 5 с, либо файл не открыт</td><td>5 Гц</td><td>красный, часто</td></tr></tbody></table><h2 id="_8-диагностика" tabindex="-1">8. Диагностика <a class="header-anchor" href="#_8-диагностика" aria-label="Permalink to &quot;8. Диагностика&quot;">​</a></h2><p>Регистратор раз в секунду публикует своё состояние: поток и загрузку каждой шины, запись на карту, потери по причинам, самую долгую операцию карты, загрузку процессора, память и температуру. Его показывает панель, оно же пишется в ULog, а команда <code>can_logger status</code> в консоли контроллера выводит его текстом. Потери разделены на две причины: переполнение буфера означает, что карта не успевает, переполнение очереди драйвера — что задача приёма не успела её вычитать. Доля потерь считается от всех кадров на шине, включая те, что драйвер потерял до регистратора.</p><h2 id="dashboard" tabindex="-1">9. Панель <a class="header-anchor" href="#dashboard" aria-label="Permalink to &quot;9. Панель {#dashboard}&quot;">​</a></h2><p>Панель работает на компьютере или телефоне и связывается с регистратором по USB или через Wi-Fi-модуль PW-Link. На компьютере страница открывается в браузере, на Android — внутри приложения. Регистратор пишет и без неё: панель нужна, чтобы проверить запись, поставить отметки событий, забрать файлы и поменять настройки, не снимая карту.</p>',30)),o(e,{name:"am_can_logger_dashboard.webp",alt:"Панель: сессии на карте, загрузка шин CAN и поток записи на карту"}),t[1]||(t[1]=a('<h3 id="_9-1-запуск" tabindex="-1">9.1. Запуск <a class="header-anchor" href="#_9-1-запуск" aria-label="Permalink to &quot;9.1. Запуск&quot;">​</a></h3><p>Для штатной работы используйте готовое приложение <strong>AM CAN logger tools</strong>: <a href="./user-guide#подключение-к-дэшборду">получение и запуск</a>. В готовых сборках Python уже включён. Для запуска из исходников нужны Python 3 и пакеты <code>pymavlink</code> и <code>pyserial</code>. Порт регистратора одновременно может держать только одна программа, поэтому QGroundControl и другие инструменты на этом порту закрывают.</p><table tabindex="0"><thead><tr><th>Где регистратор</th><th>Что запускать</th></tr></thead><tbody><tr><td>На этом компьютере</td><td><code>python3 dashboard.py --port &lt;порт&gt;</code>, страница — <code>http://localhost:8080</code></td></tr><tr><td>На компьютере площадки, доступном по SSH</td><td><code>remote_dashboard.sh &lt;пользователь&gt;@&lt;адрес&gt;</code> (на Windows — <code>python am_canlog.py remote &lt;пользователь&gt;@&lt;адрес&gt;</code>): панель работает там, страница открывается здесь на <code>http://localhost:8080</code> через SSH-туннель</td></tr><tr><td>Там же, постоянно</td><td>Панель ставится на том компьютере службой (<code>canlog_service.sh install</code>): она переживает сбои и перезагрузки, а <code>remote_dashboard.sh</code> подключается к ней</td></tr></tbody></table><p>Если соединение пропало (ноутбук уснул или сменил сеть), панель, запущенная через <code>remote_dashboard.sh</code>, сама останавливается через 15 минут без открытых страниц и освобождает порт регистратора. Служба не останавливается; перед прошивкой регистратора её останавливают (<code>canlog_service.sh stop</code>).</p><h4 id="выбор-подключения" tabindex="-1">Выбор подключения <a class="header-anchor" href="#выбор-подключения" aria-label="Permalink to &quot;Выбор подключения&quot;">​</a></h4><p>На компьютере при первом запуске готового приложения режим <code>auto</code> выбирает подключённый по USB регистратор, а при его отсутствии — Wi-Fi через UDP, порт 14550. При следующих запусках используется ранее выбранное подключение. Изменить его можно нажатием на индикатор подключения рядом с названием панели или через <code>Change…</code> в настройках. В приложении Android используется Wi-Fi. Пароль PW-Link по умолчанию — <code>cuavwlink</code>, если он не изменён (<a href="https://store.cuav.net/cuav-pw-link-docs-tutorial-firmware-troubleshooting/" target="_blank" rel="noreferrer">документация CUAV</a>).</p><p>Если данные не появляются, проверьте подключение к нужной сети PW-Link или USB-порту и выбранный канал в панели. Для Wi-Fi брандмауэр Windows должен разрешать приложению сетевой доступ. Для USB порт не должен быть занят QGroundControl или другой программой.</p><h4 id="завершение-локального-приложения" tabindex="-1">Завершение локального приложения <a class="header-anchor" href="#завершение-локального-приложения" aria-label="Permalink to &quot;Завершение локального приложения&quot;">​</a></h4><p>В Windows готовое приложение запускает сервер как фоновый процесс без отдельного окна. Для обычного завершения используйте <code>Quit</code> в панели; локальное приложение также останавливается при закрытии последней вкладки. Если процесс нужно завершить вручную, откройте диспетчер задач (<code>Ctrl+Shift+Esc</code>), в разделе «Процессы» найдите <code>am_canlog</code>, выберите его и нажмите «Завершить задачу». Имя процесса зависит от имени скачанного файла; на примере ниже показана сборка без номера версии в имени.</p>',9)),o(e,{name:"am_can_logger_task_manager.webp",alt:"Фоновый процесс AM CAN logger в диспетчере задач Windows и кнопка «Завершить задачу»"}),t[2]||(t[2]=a('<p>Остановка приложения закрывает доступ к локальной панели, но регистратор продолжает автономную запись при наличии питания.</p><h4 id="доступ-по-ссылке" tabindex="-1">Доступ по ссылке <a class="header-anchor" href="#доступ-по-ссылке" aria-label="Permalink to &quot;Доступ по ссылке&quot;">​</a></h4><p>Кнопка «Поделиться» в заголовке открывает панель в интернете для тех, у кого нет доступа к сети площадки, и закрывает её снова.</p><ul><li>Вход — по одному общему паролю; окно кнопки показывает ссылку и пароль и копирует их для отправки.</li><li>Вход действует 30 дней; смена пароля выходит всех.</li><li>Выбор сохраняется после перезапусков; у службы с постоянным именем ссылка не меняется.</li><li>Трафик идёт через внешний туннельный сервис, который может его видеть; при первом открытии сервис может показать свою страницу-предупреждение.</li><li>Вошедший может всё, что можно на месте: перезагрузить регистратор, поменять настройки, удалить файлы. Ссылку выключают, когда она не нужна.</li></ul><h3 id="_9-2-заголовок" tabindex="-1">9.2. Заголовок <a class="header-anchor" href="#_9-2-заголовок" aria-label="Permalink to &quot;9.2. Заголовок&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Элемент</th><th>Что показывает</th></tr></thead><tbody><tr><td>Состояние записи</td><td>Кадры в секунду и поток на карту; красный, пока теряются кадры. При наведении — каждая шина (поток, загрузка, скорость, потери в драйвере), потери по причинам, запись на карту и на сколько хватит свободного места</td></tr><tr><td>Здоровье</td><td>Загрузка процессора, память и температура процессора регистратора, средние за 5 с, и трафик страницы; жёлтый и красный — у пределов. При наведении — температуры IMU и барометра, канал до регистратора и задержка до панели</td></tr><tr><td>Кто здесь</td><td>Сколько человек открыли панель; при наведении — имена и последние действия, чтобы никто не перезагрузил регистратор посреди чужой выгрузки</td></tr><tr><td>Место на карте</td><td>Свободное место по данным самой карты</td></tr><tr><td>Кнопки</td><td>Доступ по ссылке, настройки, обновление списка файлов, перезагрузка регистратора, освобождение места, язык (английский, русский, татарский, хинди, испанский)</td></tr></tbody></table><p>Перезагрузка закрывает текущую сессию и начинает новую.</p><h3 id="_9-3-графики" tabindex="-1">9.3. Графики <a class="header-anchor" href="#_9-3-графики" aria-label="Permalink to &quot;9.3. Графики&quot;">​</a></h3><ul><li>«Шины CAN» — загрузка каждой шины с учётом битов стаффинга; заливка над линией — самые загруженные 100 мс. Зоны: зелёная до 50 %, оранжевая до 80 %, выше — красная. Подсказка легенды говорит, сколько кадров в секунду составляет полную шину при текущем трафике.</li><li>«SD-карта» — запись CAN, ULog, их сумма и потери. Зоны показывают ожидаемые потери при такой сумме: зелёная — без потерь, оранжевая — до 1 %, красная — больше. Предел здесь — остановки карты: каждая теряет то, что шины прислали сверх буфера, поэтому зоны считаются по самым долгим остановкам за последний час.</li></ul><p>Окно — 2, 10 или 30 минут из часа истории, которую хранит панель. Пауза (кнопка или пробел) останавливает графики, а данные продолжают копиться.</p><h3 id="_9-4-отметки-событии" tabindex="-1">9.4. Отметки событий <a class="header-anchor" href="#_9-4-отметки-событии" aria-label="Permalink to &quot;9.4. Отметки событий&quot;">​</a></h3><p>Перед действием на машине оператор пишет, что сейчас произойдёт («сейчас нажму запуск двигателя»), и нажимает «Отметить». Отметка сразу уходит на регистратор, даже во время выгрузки файла, и ложится в два места: в ULog, где её показывают PlotJuggler и Flight Review, и в файл <code>&lt;время&gt;_events.log</code> рядом с записью CAN, на часах кадров. На графиках отметки пронумерованы и перечислены под ними; страница сообщает, когда регистратор подтвердил отметку. В скобках после текста стоит имя, заданное в «Кто здесь».</p><p>При подключении панель выставляет часы регистратора по часам компьютера, поэтому время в записи и отметках настоящее. Без панели и без GPS часы после каждого включения начинаются с 2000 года, и тогда сессии различают по отметкам.</p><h3 id="_9-5-фаилы-на-карте" tabindex="-1">9.5. Файлы на карте <a class="header-anchor" href="#_9-5-фаилы-на-карте" aria-label="Permalink to &quot;9.5. Файлы на карте&quot;">​</a></h3><ul><li>Каждая сессия — одна строка: записи CAN, журнал ULog и отметки, новые сверху. В строке видна первая отметка сессии, остальные — в подсказке.</li><li>Отмеченные сессии, папку дня или всё сразу можно скачать или удалить. Записываемую сейчас сессию удалить нельзя, её файл держит регистратор; чтобы очистить карту полностью, регистратор сначала перезагружают.</li><li>Щелчок по файлу записи показывает сводку, не скачивая его: начало и конец, длительность, число кадров, поток, кадры по шинам. Панель читает только концы файла, поэтому число кадров оценочное и помечено «≈».</li></ul>',15)),o(e,{name:"am_can_logger_capture.webp",alt:"Сводка файла записи CAN и разбор шин по его началу"}),t[3]||(t[3]=a('<h4 id="выгрузка" tabindex="-1">Выгрузка <a class="header-anchor" href="#выгрузка" aria-label="Permalink to &quot;Выгрузка&quot;">​</a></h4><p>Файл идёт с регистратора на компьютер с панелью, где и остаётся, чтобы не тянуть его с карты повторно, а оттуда — на компьютер, где открыта страница: в папку загрузок браузера или в выбранную папку (Chrome и Edge). Записи CAN сохраняются как текст <code>candump</code>; вариант «как записано» (<code>.amcan</code>) втрое меньше. По USB выгрузка идёт со скоростью около 0,5 МБ/с. Файлы передаются по одному: PX4 ведёт один сеанс передачи файлов, поэтому очередь видна в панели, а передача из QGroundControl по тому же каналу прерывает выгрузку.</p><h3 id="_9-6-разбор-шин" tabindex="-1">9.6. Разбор шин <a class="header-anchor" href="#_9-6-разбор-шин" aria-label="Permalink to &quot;9.6. Разбор шин&quot;">​</a></h3><p>Протокол каждой шины задаётся в настройках или определяется по кадрам; панель пишет, по каким признакам. Разбор работает без файлов описаний (DBC, EDS):</p><table tabindex="0"><thead><tr><th>Протокол</th><th>Что видно</th></tr></thead><tbody><tr><td>DroneCAN</td><td>Узлы, их состояние и режим из NodeStatus, типы сообщений каждого узла</td></tr><tr><td>CANopen</td><td>Узлы, состояние и период heartbeat, аварийные сообщения EMCY</td></tr><tr><td>J1939</td><td>Устройства по address claim; неисправности DM1 с SPN и FMI, включая многопакетные; обороты, температура охлаждающей жидкости, давление масла, напряжение, моточасы и расход топлива двигателя</td></tr></tbody></table><p>Для каждой шины перечислены все типы сообщений с отправителями и числом кадров. Разбор файла на карте читает его первые 512 КиБ, около 5 с двух загруженных шин; скачанный файл разбирается целиком.</p><h3 id="_9-7-сниффер" tabindex="-1">9.7. Сниффер <a class="header-anchor" href="#_9-7-сниффер" aria-label="Permalink to &quot;9.7. Сниффер&quot;">​</a></h3>',7)),o(e,{name:"am_can_logger_sniffer.webp",alt:"Вкладка «Сниффер»: протокол, узлы и сообщения на каждой шине по живому потоку кадров"}),t[4]||(t[4]=d("p",null,"Вкладка «Сниффер» показывает тот же разбор по живому потоку кадров, а под ним — каждый идентификатор с частотой и последними данными. Регистратор шлёт поток, только пока вкладка открыта: по USB — каждый кадр, через беспроводной модуль — около 40 кадров в секунду целыми сообщениями, примерно 1 КиБ/с. На запись поток не влияет. Переключатель на вкладке выключает его совсем, для страницы и для GUI Tool; выбор сохраняется.",-1)),t[5]||(t[5]=d("p",null,[r("Тот же поток получает DroneCAN GUI Tool в сборке с интерфейсом "),d("code",null,"udp:"),r(": CAN1 — "),d("code",null,"udp:127.0.0.1:57740"),r(", CAN2 — "),d("code",null,"udp:127.0.0.1:57741"),r(". У каждой шины свои номера узлов, поэтому шины не сливаются в один интерфейс. При удалённом подключении адреса те же на своём компьютере: поток идёт через тот же SSH-туннель. Всё, что GUI Tool отправляет, отбрасывается: регистратор не передаёт в шины.")],-1)),t[6]||(t[6]=d("h3",{id:"_9-8-настроики",tabindex:"-1"},[r("9.8. Настройки "),d("a",{class:"header-anchor",href:"#_9-8-настроики","aria-label":'Permalink to "9.8. Настройки"'},"​")],-1)),o(e,{name:"am_can_logger_settings.webp",alt:"Окно настроек регистратора"}),t[7]||(t[7]=a('<table tabindex="0"><thead><tr><th>Настройка</th><th>Параметр</th><th>Замечание</th></tr></thead><tbody><tr><td>Шины, скорость, протокол</td><td><code>CANLOG_IFACES</code>, <code>CANLOG_BITRATE1/2</code>, <code>CANLOG_PROTO1/2</code></td><td>Список скоростей показывает, сколько кадров в секунду шина несёт при текущем трафике</td></tr><tr><td>Только прослушивание</td><td><code>CANLOG_SILENT</code></td><td>Выключают только на стенде, где больше некому подтверждать кадры</td></tr><tr><td>Длина файла</td><td><code>CANLOG_ROT_S</code></td><td>0 — один файл на сессию</td></tr><tr><td>Буфер</td><td><code>CANLOG_BUF_KB</code></td><td>Размер, который не помещается в память, регистратор уменьшает вдвое; панель показывает, сколько используется</td></tr><tr><td>Запуск при включении</td><td><code>CANLOG_EN</code></td><td></td></tr><tr><td>Содержимое ULog</td><td><code>SDLOG_PROFILE</code></td><td>Состояние регистратора или полный журнал PX4, с сырыми данными IMU или без</td></tr></tbody></table><p>Регистратор сохраняет настройки сразу, а применяет после перезагрузки; «Сохранить и перезагрузить» делает и то и другое. Каждое записанное значение панель сверяет с тем, что вернул регистратор.</p><p>При автоподборе регистратор слушает шину на скоростях 500, 250, 1000, 125, 800, 50, 20 и 10 кбит/с по очереди, пока не придут два кадра: на неверной скорости кадры не проходят проверку CRC. Первый файл ждёт скорость до 2,5 с, чтобы записать её в заголовок; кадры за это время копятся в буфере. Если позже на шине 3 с подряд одни ошибки, например регистратор переставили на другую шину, скорость определяется заново и начинается новый файл.</p><h2 id="_10-известные-ограничения" tabindex="-1">10. Известные ограничения <a class="header-anchor" href="#_10-известные-ограничения" aria-label="Permalink to &quot;10. Известные ограничения&quot;">​</a></h2><ul><li>Две шины на устройство; для третьей нужен второй регистратор или внешний контроллер CAN.</li><li>Гальванической развязки CAN нет.</li><li>Без внешнего источника времени часы после каждого включения начинаются с 2000-01-01, пока их не выставит панель; интервалы между кадрами точные.</li><li>Остановки карты длятся до нескольких секунд; при плотном потоке самая длинная может стоить пачки кадров.</li><li>Файлы выгружаются по одному: PX4 ведёт один сеанс передачи файлов, и передача из QGroundControl по тому же каналу прерывает выгрузку панели.</li><li>Сжатия сверх двоичного формата нет.</li><li>Схемы мигания светодиода предварительные.</li></ul><h2 id="_11-история-документа" tabindex="-1">11. История документа <a class="header-anchor" href="#_11-история-документа" aria-label="Permalink to &quot;11. История документа&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Версия</th><th>Дата</th><th>Изменения</th></tr></thead><tbody><tr><td>0.1</td><td>2026-10-01</td><td>Первая редакция даташита</td></tr><tr><td>0.2</td><td>2026-10-05</td><td>Автоподбор скорости, двоичная запись, отметки событий, состояние в ULog, веб-панель, конфигурация 22001; потери за 50 ч на стенде</td></tr><tr><td>0.3</td><td>2026-10-15</td><td>Описание панели перенесено в даташит</td></tr></tbody></table>',7))])}const g=l(n,[["render",s]]);export{N as __pageData,g as default};
